from __future__ import annotations

import pandas as pd
from lightgbm import LGBMClassifier


def fit_predict(train_csv: str, test_rows: list[dict[str, str]]) -> list[float]:
    train = pd.read_csv(train_csv)

    # Normalize empty strings to consistent missing marker in train
    for col in train.columns:
        if col != "y" and train[col].dtype == object:
            train[col] = train[col].replace("", "<missing>")

    y = train.pop("y").astype(int)

    test = pd.DataFrame(test_rows, columns=train.columns)

    # Normalize empty strings to same marker in test, then encode types
    for name in train.columns:
        if pd.api.types.is_numeric_dtype(train[name]):
            test[name] = pd.to_numeric(test[name])
        else:
            test[name] = test[name].replace("", "<missing>")

    # Create unified categories from train+test to avoid misalignment
    for name in train.columns:
        if train[name].dtype.name == "category":
            categories = list(train[name].cat.categories)
            for val in test[name].unique():
                if val not in categories:
                    categories.append(val)
            train[name] = train[name].cat.add_categories([c for c in categories if c not in train[name].cat.categories])
            test[name] = test[name].astype(pd.CategoricalDtype(categories=categories))

    model = LGBMClassifier(random_state=20261114, n_jobs=1, verbosity=-1)
    model.fit(train, y)
    return model.predict_proba(test)[:, 1].tolist()
